using System.Collections.Generic;
using UnityEngine;
using System;

public class SpawnerVillagerTracker : MonoBehaviour
{
    [SerializeField] private List<Villager> villagersInSpawner = new List<Villager>();
    [SerializeField] private float detectionRadius = 1f;

    public event Action<Villager> OnVillagerEntered;
    public event Action<Villager> OnVillagerExited;

    public IReadOnlyList<Villager> VillagersInSpawner => villagersInSpawner;
    public int VillagerCount => villagersInSpawner.Count;
    public bool HasVillagers => villagersInSpawner.Count > 0;

    private void OnTriggerEnter2D(Collider2D other)
    {
        var villager = other.GetComponent<Villager>();
        if (villager != null && !villagersInSpawner.Contains(villager))
        {
            villagersInSpawner.Add(villager);
            OnVillagerEntered?.Invoke(villager);
        }
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        var villager = other.GetComponent<Villager>();
        if (villager != null && villagersInSpawner.Contains(villager))
        {
            villagersInSpawner.Remove(villager);
            OnVillagerExited?.Invoke(villager);
        }
    }

    public bool IsVillagerInSpawner(Villager villager)
    {
        return villagersInSpawner.Contains(villager);
    }

    public Villager GetRandomVillager()
    {
        if (villagersInSpawner.Count == 0) return null;
        return villagersInSpawner[UnityEngine.Random.Range(0, villagersInSpawner.Count)];
    }

    public List<Villager> GetVillagersByOwnerType(OwnerType ownerType)
    {
        return villagersInSpawner.FindAll(v => v.OwnerType == ownerType);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, detectionRadius);

        Gizmos.color = Color.red;
        foreach (var villager in villagersInSpawner)
        {
            if (villager != null)
            {
                Gizmos.DrawLine(transform.position, villager.transform.position);
            }
        }
    }
#endif
}
